import json
import sys
from pathlib import Path


def search_key(title):
    return title.casefold()


def load(path="data/books.json"):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def build_export(rows):
    """Search export: every (isbn, edition) row, inactive ones flagged via "active".

    Sorted by (key, isbn, edition) so output does not depend on import order.
    """
    books = [
        {"isbn": r["isbn"], "edition": r["edition"], "title": r["title"],
         "active": r["active"], "key": search_key(r["title"])}
        for r in rows
    ]
    books.sort(key=lambda b: (b["key"], b["isbn"], b["edition"]))
    return {"books": books}


def write_export(dest="build/search.json", source="data/books.json"):
    dest = Path(dest)
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(json.dumps(build_export(load(source)), ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8")
    return dest


def prefix_search(export, prefix, include_inactive=False):
    p = search_key(prefix)
    return [b for b in export["books"]
            if b["key"].startswith(p) and (include_inactive or b["active"])]


def main(argv):
    if not argv:
        rows = load()
        print(json.dumps({"rows": len(rows), "unique_isbns": len({r["isbn"] for r in rows}),
                          "keys": [search_key(r["title"]) for r in rows]}, ensure_ascii=False))
    elif argv[0] == "build":
        print(write_export(*argv[1:2]))
    elif argv[0] == "search" and len(argv) >= 2:
        export = build_export(load())
        for b in prefix_search(export, argv[1], "--all" in argv[2:]):
            print(b["isbn"], b["edition"], b["title"], sep="\t")
    else:
        raise SystemExit("usage: catalog.py [build [DEST] | search PREFIX [--all]]")


if __name__ == "__main__":
    main(sys.argv[1:])
EOF
cat >> tests/test_catalog.py <<'EOF'


def test_export_schema_and_keys():
    from catalog import build_export
    books = build_export(load())["books"]
    assert len(books) == 4
    assert all(set(b) == {"isbn", "edition", "title", "active", "key"} for b in books)
    strasse = [b for b in books if b["title"] == "Straße Atlas"]
    assert len(strasse) == 2 and all(b["key"] == "strasse atlas" for b in strasse)


def test_prefix_search_uses_casefold():
    from catalog import build_export, prefix_search
    export = build_export(load())
    assert len(prefix_search(export, "STRASSE")) == 2
    assert [b["title"] for b in prefix_search(export, "APP")] == ["apple Almanac"]
    assert prefix_search(export, "zeb") == []
    assert len(prefix_search(export, "zeb", include_inactive=True)) == 1
